bounded_host_request.command:
set -euo pipefail
python3 - <<'PY'
import subprocess,json,sys
chat,topic=-1003770334893,4
query=f"SELECT message_id FROM topic_dm_entry_pins WHERE chat_id={chat} AND message_thread_id={topic} AND state='published' AND pinned=TRUE AND token_hash IS NOT NULL"
cmd=["docker","exec","deploy-postgres-1","sh","-c",'''exec psql -X -q -U "${POSTGRES_USER:-postgres}" -d "${POSTGRES_DB:-postgres}" -At -v ON_ERROR_STOP=1 -c "$1"''',"sh",query]
p=subprocess.run(cmd,capture_output=True,text=True,timeout=25)
if p.returncode:sys.exit(70)
ids=[x.strip() for x in p.stdout.splitlines() if x.strip()]
if len(ids)!=1 or not ids[0].isdigit() or int(ids[0])<=0:sys.exit(71)
mid=int(ids[0])
script="""import {readFileSync} from 'node:fs';
const f=process.env.BOT_TOKEN_FILE;
if(!f?.startsWith('/run/secrets/'))process.exit(31);
const token=readFileSync(f,'utf8').trim();
if(!/^[0-9]{7,15}:[A-Za-z0-9_-]{30,100}$/.test(token))process.exit(32);
const obj=JSON.parse(process.argv[1]);
const response=await fetch('https://api.telegram.org/bot'+token+'/pinChatMessage',{
 method:'POST',headers:{'Content-Type':'application/json'},
 body:JSON.stringify({chat_id:obj.chat,message_id:obj.message,disable_notification:true})
});
const body=await response.json();
if(body.ok!==true){console.error('TELEGRAM_PIN_API_REJECTED',body.error_code);process.exit(body.error_code===400?34:35);}
console.log('GAY_EXISTING_MESSAGE_PIN_REQUEST=PASS');
"""
r=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","--input-type=module","-e",script,json.dumps({"chat":chat,"message":mid})],capture_output=True,text=True,timeout=45)
if r.returncode:
 print("GAY_PIN_REJECT_CLASS",r.returncode)
 sys.exit(80 if r.returncode==34 else 81)
print("GAY_RECORDED_MESSAGE_PIN_API_PASS")
